// src/app/(app)/_layout.tsx
// Planted: the group layout opens the permission prompt at launch through the reminder sync.
import { Stack } from 'expo-router';
import { useEffect } from 'react';

import { useReminderWiring } from '@/features/reminders/use-reminder-wiring';
import { useReminderSync } from '@/hooks/use-reminder-sync';
import { useReminderTaps } from '@/hooks/use-reminder-taps';

export default function AppLayout() {
  const { sync: reminderSync, notifications, t, openReminder } = useReminderWiring();
  useEffect(() => { void reminderSync.enable(); }, [reminderSync]);
  useReminderSync(reminderSync, t);
  useReminderTaps(notifications, openReminder);
  return <Stack />;
}

// app.config.ts
import type { ExpoConfig } from 'expo/config';

export default (): ExpoConfig => ({
  name: 'Tasks', slug: 'tasks',
  android: { permissions: ['android.permission.USE_EXACT_ALARM'] },
});

// src/services/create-root-kits.ts
// Planted: the handler is handed to a push adapter the app does not have.
import { createExpoLocalNotificationsAdapter } from '@/services/local-notifications/expo-local-notifications-adapter';
import { createLocalNotificationsKit } from '@/services/local-notifications/local-notifications-root-kit';

export function createRootKits({ data, services, sync }) {
  const notifications = createExpoLocalNotificationsAdapter({ errorLog: data.errorLog, installForegroundHandler: false });
  return [createLocalNotificationsKit({ notifications, sync, hrefForReminder: () => '/' })];
}

// src/services/push/expo-push-adapter.ts
import { setNotificationHandler } from 'expo-notifications';

export function installPushHandler(): void {
  setNotificationHandler({
    handleNotification: () =>
      Promise.resolve({ shouldShowBanner: false, shouldShowList: true, shouldPlaySound: false, shouldSetBadge: false }),
  });
}

// src/app/_layout.tsx
import { Slot } from 'expo-router';
import { useEffect } from 'react';

import { useReminderWiring } from '@/features/reminders/use-reminder-wiring';

export default function RootLayout() {
  const { notifications } = useReminderWiring();
  useEffect(() => { notifications.requestPermission().catch(() => undefined); }, [notifications]);
  return <Slot />;
}

// src/features/tasks/use-tasks-model.ts
// Planted: the home screen's model turns reminders on when it mounts, so the prompt opens at launch.
import { useEffect } from 'react';

import { useServices } from '@/services/services-context';

export function useTasksModel(): { readonly remindMe: () => void } {
  const { reminderSync } = useServices();
  useEffect(() => {
    void reminderSync.enable();
  }, [reminderSync]);
  return { remindMe: () => void reminderSync.enable() };
}

// src/services/push/expo-push-adapter.ts
import { scheduleNotificationAsync } from 'expo-notifications';

export function showNow(title: string): Promise<string> {
  return scheduleNotificationAsync({ content: { title }, trigger: null });
}

// src/features/tasks/use-task-reminder.ts
import { getPermissionsAsync } from 'expo-notifications';

export const canRemind = async (): Promise<boolean> => (await getPermissionsAsync()).granted;

// src/features/tasks/reminder-permission.test.ts
// Planted: one value name in a braced list makes the whole import a value import, even in a test.
import { type NotificationResponse, getPermissionsAsync } from 'expo-notifications';

it('reads the permission', async () => {
  const response: NotificationResponse | null = null;
  expect(response).toBeNull();
  await getPermissionsAsync();
});

// src/features/tasks/save-reminder.ts
import type { PlannedNotification } from '@/core/reminders/plan-reminders';
import type { LocalNotificationsPort } from '@/services/local-notifications/local-notifications-port';

export async function scheduleNow(notifications: LocalNotificationsPort, planned: readonly PlannedNotification[]): Promise<void> {
  await notifications.scheduleNotifications(planned);
}

// app.config.ts
import type { ExpoConfig } from 'expo/config';

export default (): ExpoConfig => ({
  name: 'Tasks', slug: 'tasks',
  // A library that declares USE_EXACT_ALARM in its manifest is overruled here.
  android: { blockedPermissions: ['android.permission.USE_EXACT_ALARM'] },
});

// src/services/create-root-kits.ts
// push-notifications is adopted: its adapter owns the one foreground handler.
import { createExpoLocalNotificationsAdapter } from '@/services/local-notifications/expo-local-notifications-adapter';
import { createLocalNotificationsKit } from '@/services/local-notifications/local-notifications-root-kit';
import { installPushHandler } from '@/services/push/expo-push-adapter';

export function createRootKits({ data, services, sync }) {
  installPushHandler();
  const notifications = createExpoLocalNotificationsAdapter({ errorLog: data.errorLog, installForegroundHandler: false });
  return [createLocalNotificationsKit({ notifications, sync, hrefForReminder: () => '/' })];
}

// src/features/tasks/reminder-response.ts
import { type NotificationResponse, type NotificationRequest } from 'expo-notifications';

import type { NotificationContent } from 'expo-notifications';

export type { NotificationTrigger } from 'expo-notifications';
export type Sdk = typeof import('expo-notifications');
export type Tapped = { readonly response: NotificationResponse; readonly request: NotificationRequest; readonly content: NotificationContent };

// src/services/push/expo-notifications-push-adapter.test.ts
// Type-only imports are erased before the bundle: the adapter test may name the SDK's types.
import type * as ExpoNotifications from 'expo-notifications';

jest.mock('expo-notifications');

const native = jest.requireMock<typeof ExpoNotifications>('expo-notifications');

it('reads the automock', () => {
  expect(native).toBeDefined();
});
